// Helper: load as wxBitmap (e.g. for toolbars, buttons)
inline wxBitmap GetSpyCatLogoBitmap()
{
    wxMemoryInputStream stream(spycat_logo_png, spycat_logo_png_size);
    wxImage image(stream, wxBITMAP_TYPE_PNG);
    return wxBitmap(image);
}

// Helper: load as wxImage (e.g. for scaling/manipulation)
inline wxImage GetSpyCatLogoImage()
{
    wxMemoryInputStream stream(spycat_logo_png, spycat_logo_png_size);
    return wxImage(stream, wxBITMAP_TYPE_PNG);
}

